33	/* * * * * * * * * * * * * * * * * * * * * * * 
34	Memory Layout
35	0x5000_0000 ~ 0x5020_0000       BBL
36	0x5020_0000 ~ 0x5040_0000       Boot
37	0x5040_0000 ~ 0x5060_0000       Kernel
38	0x5060_0000 ~ 0x5060_2000       Kernel Stack
39	0x5060_2000 ~ 0x5100_0000       Kernel Mem
40	0x5100_0000 ~ 0x5e00_0000       User Mem
41	0x5e00_0000 ~ 0x6000_0000       Page Table
42	* * * * * * * * * * * * * * * * * * * * * * */
43	
