76	/* These constants define the permissions on sections in the
77	   program header, p_flags. */
78	#define PF_X (1 << 0)          /* Segment is executable */
79	#define PF_W (1 << 1)          /* Segment is writable */
80	#define PF_R (1 << 2)          /* Segment is readable */
