63	static void init_pcb()
64	{
65	    kernel_pcb[0].kernel_sp = (ptr_t)kernel_stack_0;
66	    kernel_pcb[0].user_sp = (ptr_t)kernel_stack_0;
67	    kernel_pcb[0].preempt_count = 0;
68	    kernel_pcb[0].kernel_stack_base = (ptr_t)kernel_stack_0;
69	    kernel_pcb[0].user_stack_base = (ptr_t)kernel_stack_0;
70	    kernel_pcb[0].binsem_num = 0;
71	    kernel_pcb[0].pid = 0;
72	    kernel_pcb[0].type = KERNEL_PROCESS;
