43	void interrupt_helper(regs_context_t *regs, uint64_t stval, uint64_t cause)
44	{
45	    // call corresponding handler by the value of `cause`
46	    cpu_id = get_current_cpu_id();
47	    current_cpu_running = current_running[cpu_id];
48	    if(cause & SCAUSE_IRQ_FLAG){
49	        cause = cause & ~SCAUSE_IRQ_FLAG;
50	        (*irq_table[cause])(regs, stval, cause);
51	    }
52	    else{
53	        (*exc_table[cause])(regs, stval, cause);
54	    }
