34	#define SBI_CALL_0(which) SBI_CALL(which, 0, 0, 0)
35	#define SBI_CALL_1(which, arg0) SBI_CALL(which, arg0, 0, 0)
36	#define SBI_CALL_2(which, arg0, arg1) \
37	    SBI_CALL(which, arg0, arg1, 0)
38	#define SBI_CALL_3(which, arg0, arg1, arg2) \
39	    SBI_CALL(which, arg0, arg1, arg2)
