    33	
    34	    binsem_node_t *node = &binsem_nodes[binsem_id];
    35	
    36	    if(op == BINSEM_OP_LOCK){
    37	        node->sem--;
    38	        if(node->sem < 0){
    39	            do_block(&current_running[cpu_id]->list, &node->block_queue);
    40	            scheduler();
    41	        }
    42	        else{
    43	            current_running[cpu_id]->binsem_id[current_running[cpu_id]->binsem_num] = binsem_id;
    44	            current_running[cpu_id]->binsem_num++;
    45	        }
    46	    }
    47	    else if(op == BINSEM_OP_UNLOCK){
    48	        node->sem++;
    49	        current_running[cpu_id]->binsem_num--;
    50	        if(node->sem <= 0){
    51	            list_node_t * unblocked_pcb_list = node->block_queue.next;
    52	            pcb_t *unblocked_pcb = list_entry(unblocked_pcb_list, pcb_t, list);
    53	            unblocked_pcb->binsem_id[unblocked_pcb->binsem_num] = binsem_id;
    54	            unblocked_pcb->binsem_num++; 
