#include <os/list.h>
#include <os/mm.h>
#include <os/lock.h>
#include <os/sched.h>
#include <os/time.h>
#include <os/irq.h>
#include <screen.h>
#include <stdio.h>
#include <assert.h>

pcb_t pcb[NUM_MAX_TASK];
const ptr_t pid0_stack = INIT_STACK + PAGE_SIZE;
pcb_t pid0_pcb = {
    .kernel_sp = (ptr_t)pid0_stack,
    .user_sp = (ptr_t)pid0_stack,
    .preempt_count = 0,
    .pid = 0,
    .type = KERNEL_PROCESS,
    .status = TASK_RUNNING,
    .priority = 0
};

LIST_HEAD(ready_queue);
LIST_HEAD(sleep_queue);

/* current running task PCB */
pcb_t * volatile current_running;

/* global process id */
pid_t process_id = 1;

/* 
 * Only modify PCB, current_running, process_id and ready_queue
 * DO NOT STORE OR RESTORE 
 * trick: modify $tp in ret_from_exception to ensure
 * disable_preempt() and enable_preempt() modify the same PCB
 */
void scheduler(void)
{
    pcb_t *prev = current_running;
    pcb_t *next;
    list_node_t *next_node;

    /* A task that is still runnable goes back to the tail of the ready queue.
     * pid0 is the idle task and never lives in the ready queue, and a task
     * that has just blocked itself is already parked somewhere else. */
    if (prev != &pid0_pcb && prev->status == TASK_RUNNING) {
        prev->status = TASK_READY;
        prev->ready_tick = get_ticks();
        list_add_tail(&prev->list, &ready_queue);
    }

    next_node = max_priority_node();
    if (next_node == NULL) {
        /* nothing is runnable, fall back to the idle task */
        next = &pid0_pcb;
    } else {
        list_del(next_node);
        next = list_entry(next_node, pcb_t, list);
    }

    next->status = TASK_RUNNING;
    current_running = next;

    /* every task owns its own cursor position */
    screen_cursor_x = current_running->cursor_x;
    screen_cursor_y = current_running->cursor_y;
}

// sleep(seconds)
void do_sleep(uint32_t sleep_time)
{
    // 1. block the current_running
    // 2. create a timer which calls `do_unblock` when timeout
    // 3. reschedule because the current_running is blocked
    do_block(&current_running->list, &sleep_queue);
    list_node_t* parameter = &current_running->list;
    timer_create((TimerCallback)do_unblock, (void*)parameter, get_ticks() + time_base * sleep_time);
    scheduler();
}

}

// block the pcb task into the block queue
void do_block(list_node_t *pcb_node, list_head *queue)
{
    list_del(pcb_node);
    list_add_tail(pcb_node, queue);
    list_entry(pcb_node, pcb_t, list)->status = TASK_BLOCKED;
}

// unblock the `pcb` from the block queue
void do_unblock(list_node_t *pcb_node)
{
    list_del(pcb_node);
    list_add_tail(pcb_node, &ready_queue);
    list_entry(pcb_node, pcb_t, list)->status = TASK_READY;
    list_entry(pcb_node, pcb_t, list)->ready_tick = get_ticks();
}

/*
 * Pick the ready task with the highest effective priority.  The effective
 * priority is the static priority plus an ageing bonus of one point for every
 * scheduling tick the task has already spent waiting, so that a low priority
 * task cannot starve forever.  Ties are won by the task that entered the
 * ready queue first, which keeps tasks of equal priority round-robin.
 */
list_node_t* max_priority_node(void)
{
    list_node_t *node;
    list_node_t *max_node = NULL;
    uint64_t max_priority = 0;
    uint64_t current_tick = get_ticks();

    for (node = ready_queue.next; node != &ready_queue; node = node->next) {
        pcb_t *task = list_entry(node, pcb_t, list);
        uint64_t waited_tick = 0;
        uint64_t priority;

        if (current_tick > task->ready_tick) {
            waited_tick = current_tick - task->ready_tick;
        }
        priority = (uint64_t)task->priority;
        if (timer_interval != 0) {
            priority += waited_tick / timer_interval;
        }

        if (max_node == NULL || priority > max_priority) {
            max_node = node;
            max_priority = priority;
        }
    }

    return max_node;
}

uint64_t sched_used_time;
void test_sched_time(int op)
{
	int print_location = 13;
	if(op == BEGIN){
		sched_used_time = get_ticks();
	}
	else if(op == END){
		sched_used_time = get_ticks() - sched_used_time;
	    vt100_move_cursor(1, print_location);
	    printk("time_base:\t\t%d", time_base);
	    vt100_move_cursor(1, print_location + 1);
	    printk("timer_interval:\t\t%d", timer_interval);
	    vt100_move_cursor(1, print_location + 2);
	    printk("sched_used_time:\t%d", sched_used_time);
	}
}

