main: $(SRC_MAIN) user riscv.lds
	${CC} ${CFLAGS} -o main $(SRC_MAIN) ./kernel/user_programs.c -Ttext=${KERNEL_ENTRYPOINT}
```
`-Wall` with `-O0`; note **`-nostdinc`**, so only the in-tree headers exist. The kernel links at kva `0xffffffc050400000`.

The `user` target (this is what produces `include/user_programs.h`, included by `sched.c`):
```make
user: $(SRC_USER) elf2char generateMapping
	echo "" > user_programs.c
	echo "" > user_programs.h
	for prog in $(SRC_USER); do ./elf2char --header-only $$prog >> user_programs.h; done
	for prog in $(SRC_USER); do ./elf2char $$prog >> user_programs.c; done
	./generateMapping user_programs
	mv user_programs.h include/
	mv user_programs.c kernel/
```

### `tools/elf2char.c`
Converts a binary file into a C array. With `--header-only` it emits declarations of the form `extern unsigned char <mangled_name>[];` (plus `extern int _length_<name>;`); otherwise it emits the definitions as escaped `0xNN,` bytes (`escaped_file_content`, 16 bytes per line). File names are mangled by `file_name_to_variable_name` (non-alnum → `_`). This is how `_elf_main`/`_length_main` (used by `boot.c`) and each user ELF blob get embedded into the kernel image.

### `tools/generateMapping.c`
Post-processes `user_programs.h`/`user_programs.c`: it scans the header for lines starting with `extern unsigned char`, strips `_`, `test`, `elf` from each variable name (`simplify`) to derive the user-visible program name, and then appends this API:
```c
typedef struct ElfFile {
  char *file_name;
  unsigned char* file_content;
  int* file_length;
} ElfFile;

#define ELF_FILE_NUM <n>
extern ElfFile elf_files[<n>];
extern int get_elf_file(const char *file_name, unsigned char **binary, int *length);
```
with the generated body:
```c
int get_elf_file(const char *file_name, unsigned char **binary, int *length)
{
  for (int i = 0; i < N; ++i) {
    if (strcmp(elf_files[i].file_name,file_name) == 0) {
      *binary = elf_files[i].file_content;
      *length = *elf_files[i].file_length;
      return 1;
    }
  }
  return 0;
}
```
**`get_elf_file` returns 1 on hit, 0 on miss** — that 0 is your `do_exec` `-1` case. The name mangling means `./test/test_shell.elf` → variable `_test_test_shell_elf` → `simplify` strips `_`/`test`/`elf` → name **`"shell"`** (matching `get_elf_file("shell", ...)` in `main.c`); similarly `rw`, `fly`, `consensus`, `swap`. `do_show_exec` iterates `elf_files[i].file_name` for `ls`.

